def build_order(graph):
    """Return every canonical node once, dependencies first.

    Ties are broken by choosing the lexicographically smallest node that is
    currently available.  Inputs are never mutated.
    """
    if not isinstance(graph, dict):
        raise TypeError("graph must be a dict")

    deps = {}
    for key, value in graph.items():
        if not isinstance(value, list):
            raise TypeError("each dependency collection must be a list")
        node = canonical_path(key)
        bucket = deps.get(node)
        if bucket is None:
            bucket = set()
            deps[node] = bucket
        for dependency in value:
            bucket.add(canonical_path(dependency))

    for bucket in deps.values():
        for dependency in bucket:
            if dependency not in deps:
                raise ValueError("undeclared dependency: %r" % (dependency,))

    remaining = dict((node, set(bucket)) for node, bucket in deps.items())
    order = []
    while remaining:
        available = sorted(
            node for node, bucket in remaining.items() if not bucket
        )
        if not available:
            raise ValueError("cycle detected")
        chosen = available[0]
        order.append(chosen)
        del remaining[chosen]
        for bucket in remaining.values():
            bucket.discard(chosen)
    return order
